-- ============================================================
-- Quiz coverage for devops/docker and devops/kubernetes --
-- Overview through the deepest tab that exists (Docker has no
-- advanced.md, so overview/fundamentals/intermediate only;
-- Kubernetes has all four).
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- devops/docker/overview ----------
('devops', 'docker', 'overview', 'Why do containers start in milliseconds while VMs typically take much longer?', '["Containers use less disk space", "Containers share the host kernel instead of booting a separate one", "Containers are always smaller in size than VMs", "Containers do not use a filesystem"]', 1, 'A VM virtualizes hardware and boots its own full kernel; a container is just an isolated process using the host kernel directly -- no separate kernel boot means near-instant startup.', 'beginner'),
('devops', 'docker', 'overview', 'What is the actual difference between a Docker image and a Docker container?', '["They are the same thing with different names", "An image is a read-only template; a container is a running instance of that image with its own writable layer", "An image can only run once; a container can run many times", "A container is stored on disk; an image only exists in memory"]', 1, 'You can start many independent containers from the same image -- each gets its own writable layer, so changes in one never affect the image or other containers.', 'beginner'),
('devops', 'docker', 'overview', 'What mechanism does Docker use to limit how much CPU/memory a container can use?', '["Namespaces", "cgroups", "Docker Hub", "The Dockerfile ENTRYPOINT"]', 1, 'Namespaces provide isolation (what a process can see); cgroups provide resource limits (how much it can use) -- both are Linux kernel features Docker builds on, not something Docker invents itself.', 'intermediate'),
('devops', 'docker', 'overview', 'Why does putting dependency installation before copying application code in a Dockerfile matter?', '["It is only a stylistic convention with no real effect", "It lets Docker reuse the cached dependency-install layer on code-only changes, instead of reinstalling every time", "Docker requires dependencies to be installed first or the build fails", "It makes the final image smaller"]', 1, 'Docker layers are cached -- if a layer and everything before it are unchanged, it is reused rather than re-executed. Copying code first means every commit invalidates the dependency-install layer too.', 'intermediate'),
('devops', 'docker', 'overview', 'What is the main benefit of a multi-stage Dockerfile build?', '["It makes builds run in parallel", "The final image only contains what the last stage explicitly copies, so build tools never ship in production", "It automatically scans for vulnerabilities", "It removes the need for a .dockerignore file"]', 1, 'A build stage can have a full compiler toolchain that never reaches the final image -- only the compiled artifact gets copied into a minimal runtime stage, often taking an image from hundreds of MB down to tens of MB.', 'intermediate'),

-- ---------- devops/docker/fundamentals ----------
('devops', 'docker', 'fundamentals', 'What is the difference between CMD and ENTRYPOINT in a Dockerfile?', '["They are interchangeable and behave identically", "ENTRYPOINT is the fixed command a container always runs; CMD supplies default arguments to it (or is the whole command if no ENTRYPOINT is set)", "CMD only works in Linux containers, ENTRYPOINT only in Windows containers", "ENTRYPOINT cannot be overridden under any circumstances"]', 1, 'docker run myimage <args> overrides CMD entirely but appends to ENTRYPOINT -- overriding ENTRYPOINT itself requires the explicit --entrypoint flag.', 'beginner'),
('devops', 'docker', 'fundamentals', 'What is the key difference between a Docker volume and a bind mount?', '["Volumes are always faster than bind mounts", "A volume is managed entirely by Docker and is portable; a bind mount maps a specific host path directly, tightly coupled to that host", "Bind mounts persist data, volumes do not", "Volumes can only be used with databases"]', 1, 'Volumes are the recommended default for anything that needs to persist (databases, uploads); bind mounts are mainly useful for local development where you want to live-edit source code on the host.', 'beginner'),
('devops', 'docker', 'fundamentals', 'What does EXPOSE actually do in a Dockerfile?', '["It publishes the port to the host automatically", "It is documentation/metadata only -- it does not publish or open anything by itself", "It opens the port only for HTTPS traffic", "It is required for the container to accept any network connections at all"]', 1, 'Publishing a port to the host requires -p hostPort:containerPort at docker run time -- EXPOSE alone has no effect on external reachability.', 'intermediate'),
('devops', 'docker', 'fundamentals', 'On a user-defined Docker network, how do containers typically reach each other?', '["Only by hardcoded IP address", "By container name, resolved via Docker''s built-in DNS on that network", "They cannot communicate without exposing ports to the host first", "Only through the default bridge network"]', 1, 'A user-defined network gives containers DNS resolution by name (e.g. a container named "db" is reachable as db from other containers on the same network) -- the default bridge network does not provide this.', 'intermediate'),
('devops', 'docker', 'fundamentals', 'Why should containers avoid running as root by default?', '["Root processes use more memory", "If an attacker compromises a root process and finds a container-escape vector, they get root on the host too -- the container stops being a meaningful security boundary", "Docker does not allow non-root images to be pushed to a registry", "Root containers cannot use volumes"]', 1, 'A non-root USER in the Dockerfile limits what a fully compromised container process can do, both inside the container and on any host resource it could otherwise reach.', 'intermediate'),

-- ---------- devops/docker/intermediate ----------
('devops', 'docker', 'intermediate', 'A container exits with code 137. What does this most likely mean, and how do you confirm it?', '["A segmentation fault -- check for a null pointer", "SIGKILL, usually OOMKilled -- confirm with docker inspect --format=''{{.State.OOMKilled}}'' rather than assuming", "The application exited cleanly and intentionally", "A permission error inside the container"]', 1, '137 = 128+9 (SIGKILL). It is usually the OOM killer, but can also be a manual docker kill/kill -9 -- the OOMKilled field is what actually confirms the cause rather than guessing from the exit code alone.', 'intermediate'),
('devops', 'docker', 'intermediate', 'Why would `npm ci --omit=dev` before `npm run build` break a typical Node.js project''s Docker build?', '["--omit=dev is invalid npm syntax", "Build tooling (bundlers, TypeScript) usually lives in devDependencies, which --omit=dev explicitly excludes, so the build command is not found", "npm ci does not support the --omit flag", "This only breaks on Windows-based images"]', 1, 'Installing production-only dependencies before running a build step fails for most real projects, since the build tools themselves are dev dependencies -- install fully, build, then prune with npm prune --omit=dev afterward.', 'advanced'),
('devops', 'docker', 'intermediate', 'What is the practical difference between a liveness-style HEALTHCHECK and just checking that the process is still running?', '["There is no difference -- a running process is always healthy", "A process can be running but not actually serving correctly (e.g. deadlocked, or failing all requests) -- a HEALTHCHECK actively verifies the application works, not just that it exists", "HEALTHCHECK only works with docker compose, not plain docker run", "HEALTHCHECK automatically restarts the container on any failure, with no configuration needed"]', 1, 'The gap between "process is alive" and "application is actually healthy" is exactly what a real HEALTHCHECK closes -- a container can pass a simple process check and be silently broken indefinitely.', 'intermediate'),
('devops', 'docker', 'intermediate', 'Why does Kubernetes use a securityContext block in addition to a Dockerfile''s USER instruction?', '["Kubernetes ignores the Dockerfile USER instruction entirely", "securityContext enforces the same non-root/hardening intent at the orchestrator level, as a backstop independent of what the image itself declares", "USER only works for Windows containers", "securityContext replaces the need for a Dockerfile entirely"]', 1, 'runAsNonRoot in a Pod''s securityContext will refuse to start the container at all if it would run as root, regardless of what the image''s own USER instruction says -- a cluster-enforced backstop, not a replacement.', 'advanced'),
('devops', 'docker', 'intermediate', 'Why is scanning an image for vulnerabilities BEFORE pushing to a registry better than scanning after?', '["Scanning after push is technically impossible", "A pre-push scan blocks a critical vulnerability from ever reaching the registry at all, rather than being caught later by a separate, disconnected job after the image is already deployable", "Pre-push scans are faster than post-push scans", "Only pre-push scanning tools exist"]', 1, 'Scanning before push means a failing scan blocks the image from becoming available in the first place -- catching it after push means the vulnerable image was already deployable in the window before the separate scan ran.', 'intermediate'),

-- ---------- devops/kubernetes/overview ----------
('devops', 'kubernetes', 'overview', 'What problem does Kubernetes solve that a plain container runtime like Docker does not?', '["Kubernetes makes containers start faster", "Kubernetes orchestrates many containers across many machines -- rescheduling failures, load-balancing, and rolling out updates automatically to match a declared desired state", "Kubernetes replaces the need for container images entirely", "Kubernetes is only needed for single-container applications"]', 1, 'Docker runs a single container on a single host with no concept of coordinating many containers as one application -- Kubernetes continuously reconciles actual cluster state to match a declared desired state.', 'beginner'),
('devops', 'kubernetes', 'overview', 'What is etcd''s role in a Kubernetes cluster?', '["It runs the actual application containers", "It is the distributed key-value store holding all cluster state -- the real source of truth", "It is a load balancer for external traffic", "It only stores container images"]', 1, 'The API Server is the gateway all components talk through, but etcd is where cluster state actually lives -- if etcd loses quorum, the cluster cannot update state even though existing workloads keep running.', 'beginner'),
('devops', 'kubernetes', 'overview', 'If the Kubernetes API Server goes down, what happens to already-running Pods?', '["They immediately crash", "They keep running -- the API Server being unreachable does not affect Pods already scheduled and running on healthy nodes", "They get automatically deleted", "New replicas get created to compensate"]', 1, 'The control plane manages scheduling and reconciliation, not the act of a container running -- kubelet on each node keeps existing containers running independent of API Server reachability; you just cannot schedule new work or make changes until it is back.', 'intermediate'),
('devops', 'kubernetes', 'overview', 'A Pending pod has a nodeSelector requiring a label no node in the cluster has. Why won''t Cluster Autoscaler fix this by adding a node?', '["Cluster Autoscaler is broken by default and needs manual configuration", "Cluster Autoscaler cannot create a node matching constraints it isn''t configured to provision -- it correctly concludes adding a node wouldn''t help", "Node selectors disable autoscaling entirely for the whole cluster", "This scenario is impossible -- autoscalers always resolve Pending pods eventually"]', 1, 'Cluster Autoscaler only adds nodes when it can determine a new node would let a Pending pod schedule -- if no configured node pool matches the pod''s constraints, it does nothing, silently, with no error on the pod itself.', 'advanced'),
('devops', 'kubernetes', 'overview', 'Why does a Kubernetes rolling update avoid downtime by default?', '["All old Pods are deleted before any new ones start", "New Pods are only added to a Service''s routing targets once they pass their readiness probe, and old Pods are removed gradually per maxSurge/maxUnavailable settings", "Rolling updates pause all incoming traffic during the deploy", "Downtime avoidance requires a separate load balancer outside Kubernetes"]', 1, 'Traffic never hits an unready new Pod because Services only route to Pods that have passed readiness -- combined with maxSurge/maxUnavailable controlling how many Pods change at once, this is what makes the rollout gradual and safe.', 'intermediate'),

-- ---------- devops/kubernetes/fundamentals ----------
('devops', 'kubernetes', 'fundamentals', 'Why does a Pod manifest need both resource requests and resource limits set, rather than just limits?', '["Limits alone are sufficient and requests are optional decoration", "The scheduler uses requests to decide which node has room for the Pod -- without requests, scheduling decisions and features like the Horizontal Pod Autoscaler cannot work correctly", "Requests only matter for StatefulSets, not Deployments", "Setting only limits makes the Pod use less memory"]', 1, 'Requests are what the scheduler reserves capacity for; limits are the hard ceiling. HPA percentage targets are calculated against requests specifically -- omitting requests silently breaks both scheduling reasoning and autoscaling.', 'intermediate'),
('devops', 'kubernetes', 'fundamentals', 'What is the real security caveat with Kubernetes Secrets that a learner should know?', '["Secrets are fully encrypted by default and require no extra hardening", "Secrets are only base64-encoded by default, not encrypted -- anyone with RBAC read access or direct etcd access can decode them trivially", "Secrets cannot be mounted as environment variables", "Secrets are automatically rotated every 24 hours"]', 1, 'base64 is an encoding, not encryption -- real hardening needs etcd encryption at rest or, better, an external secret manager via something like an External Secrets Operator, so credentials never live in Kubernetes'' own storage unprotected.', 'intermediate'),
('devops', 'kubernetes', 'fundamentals', 'What is the difference between a livenessProbe and a readinessProbe?', '["They are two names for the same feature", "Liveness failing restarts the container; readiness failing removes the Pod from Service routing without restarting it", "Readiness probes only run once at startup", "Liveness probes only apply to StatefulSets"]', 1, 'A Pod that is temporarily overloaded and slow should fail readiness (stop receiving new traffic, get time to recover) without being killed by a failing liveness probe for the same reason -- conflating the two causes unnecessary restarts under load.', 'intermediate'),
('devops', 'kubernetes', 'fundamentals', 'A Deployment manifest uses apiVersion: apps/v1. Is this current?', '["No, apps/v1 was deprecated in favor of extensions/v1beta1", "Yes -- apps/v1 is the current, stable API version for Deployments on all supported Kubernetes versions", "Only for StatefulSets, Deployments need a different version", "It depends on the cloud provider"]', 1, 'extensions/v1beta1 and apps/v1beta1 are the deprecated, legacy versions -- apps/v1 has been the correct, stable version for Deployments/StatefulSets/DaemonSets for a long time now.', 'beginner'),
('devops', 'kubernetes', 'fundamentals', 'Why is an Ingress resource alone not enough to route external traffic into a cluster?', '["Ingress resources are purely documentation and have no function", "Ingress needs an Ingress Controller actually running in the cluster to do anything -- the resource alone defines routing rules with nothing to enforce them", "Ingress only works with ClusterIP Services, never LoadBalancer", "Ingress requires a paid Kubernetes distribution"]', 1, 'This is a common beginner misconception -- creating an Ingress object with no controller installed (nginx-ingress, an cloud-managed one, etc.) results in rules that are simply never acted on.', 'beginner'),

-- ---------- devops/kubernetes/intermediate ----------
('devops', 'kubernetes', 'intermediate', 'What is the single most common root cause when a Service isn''t routing traffic to any Pods?', '["A firewall blocking all cluster traffic", "A label-selector mismatch between the Service and the Pods -- the Service exists but has nothing matching to route to", "DNS is always broken by default", "Services cannot route to more than one Pod"]', 1, 'A Service selects backing Pods via label selectors, not by name -- a Service with zero matching Pods still exists and accepts connections, it just has nowhere to send them. This is the most common "Service isn''t working" cause, not a networking bug.', 'intermediate'),
('devops', 'kubernetes', 'intermediate', 'Why are StatefulSet Pods not automatically rescheduled onto a different node when their node fails, unlike Deployment Pods?', '["StatefulSets do not support automatic recovery at all", "To avoid the same PersistentVolume being attached to two Pod instances simultaneously, which could corrupt data", "StatefulSet Pods are stateless and do not need rescheduling", "This is a bug that will be fixed in a future Kubernetes version"]', 1, 'This is a deliberate safety behavior, not a limitation -- a permanently-dead node hosting a StatefulSet Pod needs manual intervention (deleting the Pod) before Kubernetes will recreate it elsewhere.', 'advanced'),
('devops', 'kubernetes', 'intermediate', 'What does a PersistentVolumeClaim actually represent?', '["The physical disk itself", "A request for storage by a Pod, matched against available PersistentVolumes (or dynamically provisioned via a StorageClass)", "A backup of a Pod''s data", "A network policy for storage traffic"]', 1, 'PV is the actual cluster storage resource; PVC is a Pod-level request for some of that storage -- StorageClass enables PVCs to trigger dynamic provisioning of a new PV rather than requiring one to already exist.', 'intermediate'),
('devops', 'kubernetes', 'intermediate', 'What is the difference between a Role and a ClusterRole in Kubernetes RBAC?', '["They are identical, just different naming conventions", "A Role grants permissions within one namespace; a ClusterRole grants permissions cluster-wide or on cluster-scoped resources like nodes", "ClusterRole is deprecated in favor of Role", "Role can only be used by ServiceAccounts, never real users"]', 1, 'A common, reusable pattern: define a ClusterRole once (what is allowed) and bind it via separate namespace-scoped RoleBindings (where it applies) -- reusing one definition without granting genuinely cluster-wide access.', 'intermediate'),
('devops', 'kubernetes', 'intermediate', 'When debugging a Kubernetes networking/connectivity issue, what should you check FIRST, before assuming a networking-layer bug?', '["Reinstall the CNI plugin immediately", "Whether the Service''s label selector actually matches the target Pods'' labels -- the most common root cause is a selector mismatch, not real networking failure", "Restart every node in the cluster", "Assume it is always a DNS issue"]', 1, 'Checking label selectors first (rather than diving into networking internals) resolves the large majority of "Service isn''t working" cases quickly, since a selector mismatch looks identical to a real networking failure from the outside.', 'intermediate'),

-- ---------- devops/kubernetes/advanced ----------
('devops', 'kubernetes', 'advanced', 'A Pod has no resource requests or limits set. What QoS class does it get, and what does that mean under memory pressure?', '["Guaranteed -- it is protected from eviction", "BestEffort -- it is the first to be evicted under memory pressure, regardless of how critical the workload actually is", "Burstable -- it gets moderate eviction priority", "QoS class does not apply without explicit configuration"]', 1, 'A Pod left at defaults with no requests/limits is silently BestEffort. Deliberately setting requests and limits is what actually protects a critical service -- not naming conventions or documentation about its importance.', 'advanced'),
('devops', 'kubernetes', 'advanced', 'In the Kubernetes scheduler''s two-phase model, what does the Filter phase do versus the Score phase?', '["Filter ranks viable nodes by preference; Score removes nodes that cannot run the Pod at all", "Filter removes nodes that flatly cannot run the Pod (insufficient resources, unmatched selector, untolerated taint); Score ranks the remaining viable nodes and picks the best one", "They are the same phase run twice for redundancy", "Filter only applies to StatefulSets"]', 1, 'A Pod that is "clearly fine" resource-wise but stays Pending is almost always failing Filter on something specific -- check kubectl describe pod''s Events section for the exact filtering reason, not a scoring/preference issue.', 'advanced'),
('devops', 'kubernetes', 'advanced', 'Why can HPA and VPA both targeting CPU/memory on the SAME workload cause problems?', '["This configuration is blocked by Kubernetes automatically", "They can fight each other -- VPA resizing Pod resources while HPA is counting on stable per-replica sizing to calculate scale-out", "HPA and VPA cannot both exist in the same cluster", "VPA always takes priority and disables HPA silently"]', 1, 'This is a real, easy-to-hit misconfiguration -- HPA calculates scale-out based on per-replica resource usage relative to requests, and VPA changing those requests out from under it undermines that calculation.', 'advanced'),
('devops', 'kubernetes', 'advanced', 'What does a PodDisruptionBudget actually protect against, and what does it NOT protect against?', '["It protects against both voluntary disruptions (node drains) and involuntary ones (a node crashing)", "It protects against voluntary disruption only (node drains, evictions, rolling updates) -- it does NOT protect against involuntary disruption like a node crashing outright", "It only applies to StatefulSets, never Deployments", "It guarantees zero downtime under all circumstances"]', 1, 'This distinction matters: a PDB creates a false sense of protection if misunderstood -- minAvailable/maxUnavailable only constrain deliberate, voluntary actions like drains and evictions, not a node dying unexpectedly.', 'advanced'),
('devops', 'kubernetes', 'advanced', 'What can KEDA do that plain HPA cannot?', '["Scale based on CPU utilization", "Scale a Deployment down to zero replicas, and scale based on external event sources like queue depth or Kafka consumer lag", "KEDA and HPA have identical capabilities", "KEDA only works with StatefulSets"]', 1, 'HPA''s minReplicas floor is 1 -- it cannot scale to zero. KEDA wraps a Deployment with a ScaledObject that can scale to zero when there is genuinely nothing to process, and scales on external metrics HPA does not natively understand.', 'advanced')

ON CONFLICT (academy_slug, technology_slug, section_slug, question) DO NOTHING;
